import sys
MOD = 998244353

def main():
    input_line = sys.stdin.readline().strip()
    parts = input_line.split()
    n = int(parts[0])
    k = int(parts[1])
    l = int(parts[2])

    fac = [1] * (n + 1)
    for i in range(1, n + 1):
        fac[i] = (fac[i - 1] * i) % MOD

    dp = [[0] * (2 * n + 2) for _ in range(2 * n + 1)]
    dp[0][0] = 1

    for i in range(1, 2 * n + 1):
        for j in range(0, i + 1):
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD
            if j + 1 <= 2 * n:
                dp[i][j] = (dp[i][j] + dp[i - 1][j + 1] * (j + 1)) % MOD

    total = 0
    for i in range(k, 2 * n + 1):
        for j in range(k, n + 1):
            total = (total + dp[i][j] * dp[2 * n - i][j] % MOD * fac[j]) % MOD

    def power(base, exp, mod):
        res = 1
        while exp > 0:
            if exp & 1:
                res = (res * base) % mod
            base = (base * base) % mod
            exp >>= 1
        return res

    invA = power(dp[2 * n][0], MOD - 2, MOD)
    invB = power(2 * n + 1, MOD - 2, MOD)
    result = l * total % MOD * invA % MOD * invB % MOD
    print(result)

if __name__ == "__main__":
    main()

